"""Finalize balance-funded checkout from the invoice generated by MoySklad."""

import asyncio
from contextlib import asynccontextmanager
from copy import deepcopy
from decimal import Decimal
import hashlib
import logging
from functools import wraps

from fastapi import HTTPException
from sqlalchemy import select, text

from src.database import engine
from src.database.models import Order, OrderBenefitApplication, User
from src.integrations.moysklad.client import get_moysklad_client
from src.integrations.moysklad.settlement_checkout import (
    SOURCE_KIND, SettlementNotReady, entity_id, money, order_settlement,
    validate_settlement_invoice, check_open_settlement_orders, verify_ruble_currency,
)
from src.normalize import coerce_uuid

logger = logging.getLogger(__name__)


def serialized_settlement_checkout(function):
    @wraps(function)
    async def wrapped(session, **kwargs):
        from config import LOYALTY_USE_SETTLEMENT_BALANCE, LOYALTY_SETTLEMENT_CHECKOUT_ENABLED
        if not LOYALTY_USE_SETTLEMENT_BALANCE or not kwargs.get("use_bonus_rubles"):
            return await function(session, **kwargs)
        if not LOYALTY_SETTLEMENT_CHECKOUT_ENABLED:
            raise HTTPException(409, "Оплата с баланса временно недоступна.")
        user = kwargs["user"]
        if user.moysklad_counterparty_id is None:
            raise HTTPException(409, "Для оплаты с баланса сначала нужно связать профиль с МойСклад.")
        async with settlement_lock(user.moysklad_counterparty_id):
            if kwargs.get("draft_id"):
                from src.database.crud import get_order_by_draft_id
                existing = await get_order_by_draft_id(session, kwargs["draft_id"], user_id=user.id)
                if existing is not None:
                    return await function(session, **kwargs)
            await ensure_no_pending_balance_order(session, counterparty_id=user.moysklad_counterparty_id)
            try:
                await check_open_settlement_orders(get_moysklad_client(), user.moysklad_counterparty_id)
            except SettlementNotReady as exc:
                raise HTTPException(409, str(exc)) from exc
            except Exception as exc:
                logger.exception("Settlement preflight failed user_id=%s", user.id)
                raise HTTPException(503, "Не удалось проверить баланс в МойСклад. Заказ не создан; повторите позже.") from exc
            return await function(session, **kwargs)
    return wrapped


@asynccontextmanager
async def settlement_lock(counterparty_id):
    # A dedicated connection keeps the lock across existing service commits.
    key = int.from_bytes(hashlib.sha256(f"settlement:{counterparty_id}".encode()).digest()[:8], "big", signed=True)
    async with engine.connect() as connection:
        acquired = (await connection.execute(text("SELECT pg_try_advisory_lock(:key)"), {"key": key})).scalar()
        if not acquired:
            raise HTTPException(409, "Расчёт оплаты уже выполняется. Подождите несколько секунд.")
        try:
            yield
        finally:
            await connection.execute(text("SELECT pg_advisory_unlock(:key)"), {"key": key})


async def ensure_no_pending_balance_order(session, *, counterparty_id, exclude_order_id=None):
    query = (select(Order.id, Order.order_code, Order.checkout_snapshot)
        .join(User, User.id == Order.user_id)
        .where(User.moysklad_counterparty_id == counterparty_id,
               Order.is_canceled.is_(False), Order.is_shipped.is_(False)))
    if exclude_order_id is not None:
        query = query.where(Order.id != exclude_order_id)
    for oid, code, snapshot in (await session.execute(query)).all():
        settlement = (snapshot or {}).get("settlement_payment")
        if settlement and settlement.get("status") != "canceled":
            raise HTTPException(409, f"Баланс уже используется в заказе {code}. Завершите или отмените этот заказ перед новым списанием.")


async def confirm_settlement_invoice(session, *, order, attempts=1, client=None):
    settlement = order_settlement(order)
    if settlement is None:
        return True
    if order.is_paid:
        if settlement.get("status") != "confirmed":
            raise HTTPException(409, "Оплата уже создана, но расчёт баланса не подтверждён. Обратитесь в поддержку.")
        return True
    if order.is_canceled or order.payment_status == "refunded":
        raise HTTPException(409, "Заказ отменён или возвращён.")
    if order.moysklad_customerorder_id is None:
        raise SettlementNotReady("Заказ ещё синхронизируется с МойСклад. Повторите оплату через несколько секунд.")
    counterparty_id = coerce_uuid(settlement.get("counterparty_id"))
    if counterparty_id is None:
        raise ValueError("Missing settlement counterparty")
    user = await session.get(User, order.user_id)
    if user is None or user.moysklad_counterparty_id != counterparty_id:
        raise ValueError("Settlement customer identity changed")
    await ensure_no_pending_balance_order(session, counterparty_id=counterparty_id, exclude_order_id=order.id)
    client = client or get_moysklad_client()
    await check_open_settlement_orders(client, counterparty_id, exclude_order_id=order.moysklad_customerorder_id)
    currency_id = None
    for attempt in range(attempts):
        remote = await client.get_customer_order(order.moysklad_customerorder_id)
        if not remote:
            raise ValueError("Settlement order missing in MoySklad")
        if currency_id is None:
            currency_id = await verify_ruble_currency(client, remote)
        if money(remote.get("shippedSum", 0)) > 0:
            raise ValueError("Settlement order has already been shipped; manual reconciliation required")
        refs = remote.get("invoicesOut") or []
        invoices = []
        for ref in refs:
            iid = entity_id(ref)
            if iid is None:
                raise ValueError("Invalid settlement invoice reference")
            invoice = await client.get_invoiceout(iid)
            if invoice and not invoice.get("deleted") and invoice.get("applicable") is True:
                invoices.append(invoice)
        if len(invoices) > 1:
            raise ValueError("Multiple active MoySklad invoices; manual reconciliation required")
        if invoices:
            try:
                result = validate_settlement_invoice(remote, invoices[0],
                    order_id=order.moysklad_customerorder_id, counterparty_id=counterparty_id,
                    organization_id=coerce_uuid(settlement.get("organization_id")),
                    currency_id=currency_id,
                    gross_rubles=money(settlement["gross_rubles"]),
                    maximum_balance_rubles=money(settlement["maximum_balance_rubles"]))
                break
            except SettlementNotReady:
                pass
        if attempt + 1 < attempts:
            await asyncio.sleep(2)
    else:
        raise SettlementNotReady("МойСклад ещё рассчитывает оплату с баланса. Повторите через несколько секунд.")

    from src.app.services.benefits.moysklad_bonus import get_moysklad_settlement_wallet
    wallet = await get_moysklad_settlement_wallet(counterparty_id, moysklad_client=client)
    if result.balance_rubles > wallet.balance_rubles:
        raise HTTPException(409, "Баланс изменился. Не оплачивайте старый счёт; обратитесь к менеджеру для перерасчёта.")
    if result.balance_rubles == 0:
        raise HTTPException(409, "МойСклад не применил баланс к счёту. Оплата не создана; обратитесь к менеджеру.")
    snapshot = deepcopy(order.checkout_snapshot)
    snapshot["settlement_payment"].update({"status": "confirmed", "invoice_id": str(result.invoice_id),
        "cash_rubles": str(result.cash_rubles), "balance_rubles": str(result.balance_rubles),
        "displayed_spent_rubles": result.displayed_spent_rubles})
    benefits = snapshot["benefits"]
    previous = money(benefits.get("bonus_applied_rubles", 0))
    benefits["bonus_applied_rubles"] = float(result.balance_rubles)
    benefits["bonus_applied_points"] = result.displayed_spent_rubles
    benefits["cash_total"] = float(result.cash_rubles)
    benefits["stacked_discount_amount"] = float(money(benefits["stacked_discount_amount"]) - previous + result.balance_rubles)
    benefits["total_after_discounts"] = float(max(Decimal("0"), result.cash_rubles - order.delivery_total))
    for item in benefits.get("applications", []):
        if item.get("source_kind") == SOURCE_KIND:
            item["discount_amount"] = str(result.balance_rubles)
            item["benefit_units"] = str(result.displayed_spent_rubles)
    application = (await session.execute(select(OrderBenefitApplication).where(
        OrderBenefitApplication.order_id == order.id,
        OrderBenefitApplication.source_kind == SOURCE_KIND))).scalar_one()
    application.status = "applied"
    application.external_reference = str(result.invoice_id)
    application.discount_amount = result.balance_rubles
    application.benefit_units = result.displayed_spent_rubles
    application.calculation_snapshot = {**(application.calculation_snapshot or {}),
        "settlement_invoice_id": str(result.invoice_id), "exact_balance_rubles": str(result.balance_rubles),
        "cash_rubles": str(result.cash_rubles)}
    order.moysklad_invoiceout_id = result.invoice_id
    order.grand_total = result.cash_rubles
    order.checkout_snapshot = snapshot
    await session.commit()
    return True


async def prepare_settlement_payment(session, *, order):
    settlement = order_settlement(order)
    if settlement is None:
        return
    try:
        await confirm_settlement_invoice(session, order=order, attempts=6)
        from .crm import sync_settlement_amount_to_crm
        await sync_settlement_amount_to_crm(session, order)
    except SettlementNotReady as exc:
        raise HTTPException(409, str(exc)) from exc
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("Settlement invoice validation failed order_id=%s", order.id)
        raise HTTPException(409, "Не удалось сверить счёт с МойСклад. Оплата не создана; обратитесь в поддержку.") from exc
